function solve(a, b) {
  function parse(v) {
    const [major, minor, patch] = v.split('.').map(Number);
    const pre = v.split('-')[1]?.split('.').map(Number) || [];
    return { major, minor, patch, pre };
  }

  const va = parse(a);
  const vb = parse(b);

  if (va.major !== vb.major) return va.major > vb.major ? 1 : -1;
  if (va.minor !== vb.minor) return va.minor > vb.minor ? 1 : -1;
  if (va.patch !== vb.patch) return va.patch > vb.patch ? 1 : -1;

  if (va.pre.length === 0 && vb.pre.length === 0) return 0;
  if (va.pre.length === 0) return 1;
  if (vb.pre.length === 0) return -1;

  // Compare pre-release identifiers lexicographically
  const len = Math.min(va.pre.length, vb.pre.length);
  for (let i = 0; i < len; i++) {
    const a = va.pre[i], b = vb.pre[i];
    const na = Number(a), nb = Number(b);
    if (!isNaN(na) && !isNaN(nb)) {
      if (na !== nb) return na > nb ? 1 : -1;
    } else {
      const cmp = a.localeCompare(b, undefined, { numeric: true });
      if (cmp !== 0) return cmp > 0 ? 1 : -1;
    }
  }

  // Pre-release with fewer identifiers is newer
  return va.pre.length < vb.pre.length ? 1 : -1;
}
